INSERT INTO 
	user_activity_log (
		activity_log_num, member_num, activity_occurred_at, activity_category,
		activity_action, activity_result
)
VALUES (
	user_activity_log_seq.NEXTVAL, #{member_num},
	#{activity_occurred_at, jdbcType=TIMESTAMP_WITH_TIMEZONE},
	#{activity_category}, #{activity_action}, #{activity_result}
)

mapper.select:

SELECT COUNT(*) FROM user_activity_log 




		AND member_num = #{memberNum}




		AND activity_category = #{category}




		AND activity_result = #{result}




		AND activity_occurred_at >=
		#{startAt, jdbcType=TIMESTAMP_WITH_TIMEZONE}




		AND activity_occurred_at <
		#{endBefore, jdbcType=TIMESTAMP_WITH_TIMEZONE}

SELECT
    activity_log_num, member_num, activity_occurred_at,
    activity_category, activity_action, activity_result
FROM (
    SELECT
        activity_log_num, member_num, activity_occurred_at,
        activity_category, activity_action, activity_result,

        ROW_NUMBER() OVER (
            ORDER BY
                activity_occurred_at DESC, activity_log_num DESC
        ) AS row_num
    FROM user_activity_log




            AND member_num = #{memberNum}




            AND activity_category = #{category}




            AND activity_result = #{result}




            AND activity_occurred_at >=
                #{startAt, jdbcType=TIMESTAMP_WITH_TIMEZONE}




            AND activity_occurred_at <
                #{endBefore, jdbcType=TIMESTAMP_WITH_TIMEZONE}


)

WHERE row_num BETWEEN #{begin} AND #{end}
ORDER BY row_num
